package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct { // 01 DISC-REC, 15 bytes
	DrItem  string          // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct   int64           // PIC 9(2) @13 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsDiscount decimal.Decimal // PIC 9(5)V99 len=7 = 0
var WsNet decimal.Decimal // PIC 9(5)V99 len=7 = 0
var WsTotalNet decimal.Decimal // PIC 9(8)V99 len=10 = 0
var WsCount int64 // PIC 9(3) len=3 = 0
var WsPriceEd string // PIC ZZ,ZZ9.99 len=9
var WsDiscEd string // PIC ZZ,ZZ9.99 len=9
var WsNetEd string // PIC ZZ,ZZ9.99 len=9
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

var discRec DiscRec

var discFileLines []string
var discFileIdx int
var discFileEOF bool

func main() {
	WsEofFlag = "N"
	WsDiscount = decimal.NewFromInt(0)
	WsNet = decimal.NewFromInt(0)
	WsTotalNet = decimal.NewFromInt(0)
	WsCount = 0
	MAINPARA()
}

func MAINPARA() {
	OPENINPUTDISCFILE()
	READPARA()
	for !INPUTDONE() {
		PROCESSPARA()
	}
	CLOSEDISCFILE()
	SUMMARYPARA()
}

func READPARA() {
	if discFileIdx >= len(discFileLines) {
		WsEofFlag = "Y"
		return
	}
	line := discFileLines[discFileIdx]
	discFileIdx++
	// pad / truncate to 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	// parse
	drItemRaw := line[0:6]
	drPriceRaw := line[6:13]
	drPctRaw := line[13:15]

	discRec.DrItem = drItemRaw

	// DR-PRICE PIC 9(5)V99 -> 7 digits implied 2 decimals
	discRec.DrPrice = parsePic9V99(drPriceRaw, 2)
	// DR-PCT PIC 9(2)
	discRec.DrPct = parsePic9Int(drPctRaw)
}

func PROCESSPARA() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT / 100
	tmp := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct)).Shift(-2)
	WsDiscount = storeDecimal(tmp, 5, 2, true)

	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT
	tmp2 := discRec.DrPrice.Sub(WsDiscount)
	WsNet = storeDecimal(tmp2, 5, 2, false)

	// ADD WS-NET TO WS-TOTAL-NET
	WsTotalNet = storeDecimal(WsTotalNet.Add(WsNet), 8, 2, false)

	// ADD 1 TO WS-COUNT
	WsCount = storeInt(WsCount+1, 3)

	MOVEDRPRICETOWSPRICEED()
	MOVEWSDISCOUNTTODISCED()
	MOVEWSNETTONETED()

	// DISPLAY DR-ITEM " " WS-PRICE-ED " " DR-PCT "% " WS-DISC-ED " " WS-NET-ED
	drPctStr := fmt.Sprintf("%02d", discRec.DrPct%100)
	// For negative? Not needed, but keep width 2
	if discRec.DrPct < 0 {
		// format with sign? COBOL would show? ignore
		drPctStr = fmt.Sprintf("%02d", discRec.DrPct)
	}
	line := discRec.DrItem + " " + WsPriceEd + " " + drPctStr + "% " + WsDiscEd + " " + WsNetEd
	fmt.Fprintln(os.Stdout, line)

	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	wsCountStr := fmt.Sprintf("%03d", WsCount%1000)
	if WsCount < 0 {
		// handle negative overflow sign
		wsCountStr = fmt.Sprintf("%03d", WsCount)
	}
	// DISPLAY "ITEMS: " WS-COUNT " NET TOTAL: " WS-TOTAL-ED
	line := "ITEMS: " + wsCountStr + " NET TOTAL: " + WsTotalEd
	fmt.Fprintln(os.Stdout, line)
}

// helpers

func INPUTDONE() bool { return WsEofFlag == "Y" }

func OPENINPUTDISCFILE() {
	f, err := os.Open("input.dat")
	if err != nil {
		// file not found -> EOF
		discFileLines = []string{}
		discFileIdx = 0
		return
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// allow large lines
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 1024*1024)
	// Scanner SplitLines keeps content without \r\n, preserves spaces
	// Need to handle that Scanner strips trailing \r; we keep rest
	for scanner.Scan() {
		txt := scanner.Text()
		// Remove carriage return already done; keep spaces
		discFileLines = append(discFileLines, txt)
	}
	discFileIdx = 0
}

func CLOSEDISCFILE() {}

func parsePic9V99(raw string, scale int32) decimal.Decimal {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return decimal.NewFromInt(0)
	}
	// raw should be digits only; ignore non-digits? Parse digits
	// Keep only digits 0-9, allow sign?
	s := ""
	for _, ch := range raw {
		if ch >= '0' && ch <= '9' {
			s += string(ch)
		}
	}
	if s == "" {
		return decimal.NewFromInt(0)
	}
	d, err := decimal.NewFromString(s)
	if err != nil {
		return decimal.NewFromInt(0)
	}
	return d.Shift(-scale)
}

func parsePic9Int(raw string) int64 {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return 0
	}
	s := ""
	for _, ch := range raw {
		if ch >= '0' && ch <= '9' {
			s += string(ch)
		}
	}
	if s == "" {
		return 0
	}
	var v int64
	for _, ch := range s {
		v = v*10 + int64(ch-'0')
	}
	// keep low-order digits that fit 2 digits: if longer, truncate high
	if len(s) > 2 {
		mod := int64(1)
		for i := 0; i < 2; i++ {
			mod *= 10
		}
		v %= mod
	}
	return v
}

func storeDecimal(val decimal.Decimal, intDigits int, scale int32, rounded bool) decimal.Decimal {
	var t decimal.Decimal
	if rounded {
		t = val.Round(scale)
	} else {
		t = val.Truncate(scale)
	}
	// Overflow: keep low-order integer digits
	// pow10 = 10^intDigits
	pow10 := decimal.NewFromInt(1)
	for i := 0; i < intDigits; i++ {
		pow10 = pow10.Mul(decimal.NewFromInt(10))
	}
	neg := t.Sign() < 0
	abs := t.Abs()
	intPart := abs.Truncate(0)
	fracPart := abs.Sub(intPart)
	if intPart.GreaterThanOrEqual(pow10) {
		intPart = intPart.Mod(pow10)
	}
	resAbs := intPart.Add(fracPart)
	if neg {
		resAbs = resAbs.Neg()
	}
	// Ensure scale (Truncate already)
	return resAbs
}

func storeInt(v int64, digits int) int64 {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if v >= mod || v < 0 {
		// keep low-order digits, preserve sign for negative? COBOL high-order dropped, sign kept
		// For positive simple mod
		if v >= 0 {
			return v % mod
		}
		// negative: compute abs mod then reapply sign? COBOL stores low-order digits including sign
		abs := v
		if abs < 0 {
			abs = -abs
		}
		low := abs % mod
		return -low
	}
	return v
}

func MOVEDRPRICETOWSPRICEED() {
	WsPriceEd = formatEdited(discRec.DrPrice, "ZZ,ZZ9.99")
}
func MOVEWSDISCOUNTTODISCED() {
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
}
func MOVEWSNETTONETED() {
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")
}

func formatEdited(val decimal.Decimal, picture string) string {
	// Determine scale = count of '9' after '.'
	dotIdx := strings.Index(picture, ".")
	scale := 0
	if dotIdx >= 0 {
		for _, ch := range picture[dotIdx+1:] {
			if ch == '9' {
				scale++
			}
		}
	}
	// integer placeholder count
	intPlaceholders := 0
	if dotIdx >= 0 {
		for _, ch := range picture[:dotIdx] {
			if ch == 'Z' || ch == '9' {
				intPlaceholders++
			}
		}
	} else {
		for _, ch := range picture {
			if ch == 'Z' || ch == '9' {
				intPlaceholders++
			}
		}
	}
	// Prepare absolute value truncated to scale (edited move does not round beyond source scale)
	// But val already at correct scale; ensure truncate to scale
	v := val.Truncate(int32(scale))
	neg := v.Sign() < 0
	if neg {
		v = v.Abs()
	}
	// Split integer and fraction
	intPart := v.Truncate(0)
	fracPart := v.Sub(intPart)

	// Apply overflow dropping high-order integer digits
	pow10 := decimal.NewFromInt(1)
	for i := 0; i < intPlaceholders; i++ {
		pow10 = pow10.Mul(decimal.NewFromInt(10))
	}
	if intPart.GreaterThanOrEqual(pow10) {
		intPart = intPart.Mod(pow10)
	}

	// integer digits string zero-padded to intPlaceholders
	intStr := intPart.StringFixed(0) // no scale
	// StringFixed may produce "0"
	if len(intStr) < intPlaceholders {
		intStr = strings.Repeat("0", intPlaceholders-len(intStr)) + intStr
	} else if len(intStr) > intPlaceholders {
		// Should have been modded, but keep low-order
		intStr = intStr[len(intStr)-intPlaceholders:]
	}

	// fraction digits string zero-padded to scale
	fracStr := ""
	if scale > 0 {
		// fracPart = 0.xx ; multiply by 10^scale
		mult := decimal.NewFromInt(1)
		for i := 0; i < scale; i++ {
			mult = mult.Mul(decimal.NewFromInt(10))
		}
		fracInt := fracPart.Mul(mult).Truncate(0)
		// Due to decimal representation, need int
		fracStr = fracInt.StringFixed(0)
		if len(fracStr) < scale {
			fracStr = strings.Repeat("0", scale-len(fracStr)) + fracStr
		} else if len(fracStr) > scale {
			fracStr = fracStr[len(fracStr)-scale:]
		}
	}

	// Map integer placeholders to digits
	// Create slice of placeholder info in order
	type ph struct {
		idx int // position in picture
		isZ bool
	}
	var intPHs []ph
	for i, ch := range picture {
		if dotIdx >= 0 && i > dotIdx {
			break
		}
		if ch == 'Z' || ch == '9' {
			intPHs = append(intPHs, ph{idx: i, isZ: ch == 'Z'})
		}
	}
	// digits assignment
	digitForPH := make(map[int]byte) // picture index -> digit char
	for i, ph := range intPHs {
		digitForPH[ph.idx] = intStr[i]
	}

	// Determine suppression: walk intPHs left to right
	suppressed := true
	// Keep per PH whether it will be suppressed (space)
	suppressedPH := make(map[int]bool)
	for _, ph := range intPHs {
		d := digitForPH[ph.idx]
		if suppressed {
			if ph.isZ && d == '0' {
				suppressedPH[ph.idx] = true
				// remain suppressed
			} else {
				suppressedPH[ph.idx] = false
				suppressed = false
			}
		} else {
			suppressedPH[ph.idx] = false
		}
	}

	// Build result array
	res := []rune(picture)
	// Fill integer placeholders
	for _, ph := range intPHs {
		if suppressedPH[ph.idx] {
			res[ph.idx] = ' '
		} else {
			res[ph.idx] = rune(digitForPH[ph.idx])
		}
	}
	// Handle commas: if all more significant integer placeholders are suppressed, comma becomes space
	// For each comma before dot, check if suppressed flag holds through all PHs to its left
	for i, ch := range picture {
		if ch == ',' {
			// check if any PH with idx < i is not suppressed
			hasNonSuppressedLeft := false
			for _, ph := range intPHs {
				if ph.idx < i && !suppressedPH[ph.idx] {
					hasNonSuppressedLeft = true
					break
				}
			}
			if !hasNonSuppressedLeft {
				res[i] = ' '
			} else {
				res[i] = ','
			}
		}
	}
	// Fill fraction placeholders
	if scale > 0 {
		fracIdx := 0
		for i, ch := range picture {
			if dotIdx >= 0 && i > dotIdx {
				if ch == '9' {
					if fracIdx < len(fracStr) {
						res[i] = rune(fracStr[fracIdx])
						fracIdx++
					} else {
						res[i] = '0'
					}
				} else if ch == '.' {
					res[i] = '.'
				}
			}
		}
	}
	// Negative sign handling (not needed but for completeness, prepend '-' if picture has no sign? COBOL would drop? We'll just prefix if needed)
	if neg {
		// Find first non-space digit position to place '-' before? Simple: replace first space before first digit with '-'
		// For unsigned fields, ignore
	}
	return string(res)
}
